test("nextAvailableKey folds in the live database even when it outpaces committed source", () => {
  // The exact scenario that caused two real collisions: committed source
  // only knows about key 26, but the shared database already has 27 applied
  // from concurrent, not-yet-committed work.
  const keys = [{ name: "CONSTITUTION_PUBLICATION_HISTORY", key: 26 }];
  assert.equal(nextAvailableKey(keys, [26], [26, 27]), 28);
});

